def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_d = n - me.count('C')

    last_me = me[-1]
    last_opp = opp[-1]

    if opp_c == 0:
        return 'D'
    if n >= 3 and opp_d >= n - 1:
        return 'D'

    r5 = opp[-5:] if n >= 5 else opp
    r10 = opp[-10:] if n >= 10 else opp
    opp_d5 = r5.count('D')
    opp_d10 = r10.count('D')

    opp_d_streak = 0
    i = n - 1
    while i >= 0:
        if opp[i] == 'D':
            opp_d_streak += 1
            i -= 1
        else:
            break

    both_d_streak = 0
    i = n - 1
    while i >= 0:
        if me[i] == 'D' and opp[i] == 'D':
            both_d_streak += 1
            i -= 1
        else:
            break

    cnt_after_c = 0
    cnt_c_after_c = 0
    cnt_after_d = 0
    cnt_c_after_d = 0

    for i in range(n - 1):
        if me[i] == 'C':
            cnt_after_c += 1
            if opp[i + 1] == 'C':
                cnt_c_after_c += 1
        else:
            cnt_after_d += 1
            if opp[i + 1] == 'C':
                cnt_c_after_d += 1

    p_c_after_c = cnt_c_after_c / cnt_after_c if cnt_after_c else 1.0
    p_c_after_d = cnt_c_after_d / cnt_after_d if cnt_after_d else 0.0
    retaliation = p_c_after_c - p_c_after_d

    if opp_c * 5 < n * 2:
        return 'D'

    soft = (
        cnt_after_d >= 1
        and p_c_after_d >= 0.68
        and retaliation <= 0.28
        and opp_c * 10 >= n * 8
        and opp_d10 <= 3
    )

    if last_opp == 'D':
        soft = False

    if n >= 90 and opp_c * 10 >= n * 8 and last_opp == 'C':
        if soft:
            return 'D'
        if (
            cnt_after_d >= 1
            and p_c_after_d >= 0.55
            and retaliation <= 0.45
            and opp_d * 10 <= n * 2
        ):
            return 'D'
        if n >= 97 and opp_d <= 2 and retaliation <= 0.18 and p_c_after_d >= 0.8:
            return 'D'

    if last_opp == 'D':
        if opp_d_streak >= 3:
            return 'D'

        if last_me == 'D':
            if opp_c * 2 >= n and opp_d_streak <= 1 and both_d_streak <= 1:
                return 'C'
            return 'D'

        if n >= 2 and me[-2] == 'D' and opp_d_streak == 1 and opp_c * 10 >= n * 8:
            return 'C'

        if opp_d <= 1 + n // 25 and opp_c * 10 >= n * 9 and opp_d_streak == 1:
            return 'C'

        return 'D'

    if opp_c * 10 < n * 6:
        return 'D'

    if opp_d10 >= 4 and opp_c * 5 < n * 3:
        return 'D'

    if soft:
        return 'D'

    return 'C'
